import json, sys

def preview(s, n=300):
    s = s.replace("\n", " ")
    return s[:n] + ("…" if len(s) > n else "")

def content_summary(content):
    if isinstance(content, str):
        return preview(content)
    parts = []
    for block in content:
        if not isinstance(block, dict):
            continue
        t = block.get("type")
        if t == "text":
            parts.append("TEXT: " + preview(block.get("text", "")))
        elif t == "thinking":
            parts.append("THINKING: " + preview(block.get("thinking", ""), 150))
        elif t == "tool_use":
            parts.append(f"TOOL_USE[{block.get('name')}]: " + preview(json.dumps(block.get("input", {})), 200))
        elif t == "tool_result":
            c = block.get("content")
            if isinstance(c, list):
                c = " ".join(x.get("text", "") for x in c if isinstance(x, dict))
            parts.append("TOOL_RESULT: " + preview(str(c), 200))
        else:
            parts.append(t)
    return " | ".join(parts)

path = sys.argv[1]
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        ts = d.get("timestamp", "")
        typ = d.get("type")
        if typ in ("user", "assistant"):
            msg = d.get("message", {})
            role = msg.get("role", typ)
            content = msg.get("content", "")
            print(f"[{ts}] {role.upper()}: {content_summary(content)}")
        elif typ == "summary":
            continue

